/*
 * STM32F746G-DISCO Onboard LED Blink
 * The Discovery board has a green LED LD1 on PI1.
 * LED_BUILTIN is mapped to D13 (pin 13) automatically.
 * No external wiring required — just press Run!
 */

void setup() {
  pinMode(LED_BUILTIN, OUTPUT);
  Serial.begin(115200);
  Serial.println("STM32F746 onboard LED blink started");
}

void loop() {
  digitalWrite(LED_BUILTIN, HIGH);
  Serial.println("LD1 ON");
  delay(500);

  digitalWrite(LED_BUILTIN, LOW);
  Serial.println("LD1 OFF");
  delay(500);
}
